	this.ui.get("HL_CreditedAccount").setEnabled(false);
	this.ui.get("HL_DebitedAmount").setEnabled(false);
	this.ui.get("HL_DebitedAmount").setEnabled(false);
	this.ui.get("debitSection").setEnabled(false);
}else{
