//Init Credit Account Data
this.setAccountInfo = function (value)
 {

	for (var i=0; i<this.context.options.customerAccounts.get("value").length(); i++) 
	{
	var accountNo= this.context.options.customerAccounts.get("value").get(i).get("accountNO") ? this.context.options.customerAccounts.get("value").get(i).get("accountNO") : "";
		if (accountNo == value.getData()) { 
			var branchCode = this.context.options.customerAccounts.get("value").get(i).get("branchCode");
			var currency = this.context.options.customerAccounts.get("value").get(i).get("currencyCode");
			var balance = this.context.options.customerAccounts.get("value").get(i).get("balance");
			var balanceSign = this.context.options.customerAccounts.get("value").get(i).get("balanceType");
			var classCode = this.context.options.customerAccounts.get("value").get(i).get("accountClassCode");
	 		classCode= classCode? classCode.substring(0,1):"";
	 		
	 		this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").set("branchCode", branchCode);
	 			
	 		this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").set("balance", balance);	 		
	 		this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").set("balanceSign", balanceSign);

	 		if(classCode == "O" || classCode == "D")
	 			this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").set("isOverDraft",true);
			else
				this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").set("isOverDraft",false);
						
//			var od= this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").get("isOverDraft");
	 		//SET CURRENCY
	 		this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").set("currency", {} );
	 		this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").get("currency").set("name", currency);
	 		this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").get("currency").set("value", currency);
			
			//SET EXCHANGE RATE
//			view.setNegoRate(currency);	
 		}
	}
}
 //Set credited Amount
 this.setNegoRate = function(value)
 {	

//	console.log("----------------------INSIDE setNegoRate");
  	var liqCurr   =  this.ui.get("LiquidateionCurrency").getData()? this.ui.get("LiquidateionCurrency").getData():"";  		 	
  	var accCurr   =  value.getData()? value.getData():""; 	 	

 	if ( liqCurr != "" && accCurr != "" && ( liqCurr == accCurr ) ) { 
		this.ui.get("standardExRate").setData(1);
		this.ui.get("negotiatedExRate").setData(1);
  		this.ui.get("negotiatedExRate").setEnabled(false); 	
 	} 		

 	if ( liqCurr != "" && accCurr != "" && ( liqCurr != accCurr ) ){
		this.ui.get("negotiatedExRate").setEnabled(true);
		concatedCurrency = {ccFrom : liqCurr , ccTo : accCurr , type:"TRANSFER" , sType:"S"};
		inputCurr = JSON.stringify(concatedCurrency);
		this.ui.get("GetExchangeRate").execute(inputCurr);
 	}			
}
//SET Credited Amount From Exchange Service
 this.SetCreditAmountDetails = function(value){
	var exRate = this.context.options.exchangeRate.get("value");
	this.ui.get("standardExRate").setData( Number(exRate.toFixed(6)));
	this.ui.get("negotiatedExRate").setData( Number(exRate.toFixed(6)));

 } 
//calculate credited amount in cuurency
this.setAmountInCurrency = function(){
	var liqAmount  =  this.ui.get("LiquidationAmount").getData()? this.ui.get("LiquidationAmount").getData():0;
	var negoExRate =  this.ui.get("negotiatedExRate").getData()? this.ui.get("negotiatedExRate").getData():0;
	
	if( liqAmount > 0   &&   negoExRate > 0 )
		this.ui.get("creditedAmountinAccCurrency").setData(liqAmount * negoExRate);
}

