//On load of account class - set vis according to account class (customer & gl)
this.accountNumVis = function (value) {
    var accountClass = value.getData().name;
    
    if (!this.context.options.isChecker.get("value")) {
        if (accountClass == "Customer Account") {
            this.ui.get("glAccountNo").setVisible(false, true);
            this.ui.get("verifyGlAccountBtn").setVisible(false, true);

            this.ui.get("customerAccountNo").setVisible(true, true);

            this.ui.get("AccountBranchCode").setEnabled(false);
            this.ui.get("accountCurrency").setEnabled(false);

            this.ui.get("AccountBalance").setVisible(true,true);
            this.ui.get("AccountBalance").setEnabled(false);

            this.ui.get("BalanceSign").setVisible(true,true);
            this.ui.get("BalanceSign").setEnabled(false);

        } else if (accountClass == "GL Account") {
            this.ui.get("glAccountNo").setVisible(true, true);
            this.ui.get("verifyGlAccountBtn").setVisible(true, true);
            this.ui.get("AccountBranchCode").setEnabled(true);
            this.ui.get("accountCurrency").setEnabled(true);

            this.ui.get("customerAccountNo").setVisible(false, true);
            this.ui.get("AccountBalance").setVisible(false,true);
            this.ui.get("BalanceSign").setVisible(false,true);

        }
    } else {
        this.ui.get("AccountBranchCode").setEnabled(false);
        this.ui.get("accountCurrency").setEnabled(false);
        
        if (accountClass == "GL Account") {
            this.ui.get("glAccountNo").setVisible(true, true);
            this.ui.get("glAccountNo").setEnabled(false);
            this.ui.get("verifyGlAccountBtn").setVisible(false, true);
   
            this.ui.get("customerAccountNo").setVisible(false, true);
            this.ui.get("AccountBalance").setVisible(false, true);
            this.ui.get("BalanceSign").setVisible(false, true);
            
        } else {
            this.ui.get("glAccountNo").setVisible(false, true);
            this.ui.get("verifyGlAccountBtn").setVisible(false, true);

            this.ui.get("customerAccountNo").setVisible(true, true);
		this.ui.get("customerAccountNo").setEnabled(false);
		
            this.ui.get("AccountBalance").setVisible(true, true);
            this.ui.get("AccountBalance").setEnabled(false);

            this.ui.get("BalanceSign").setVisible(true, true);
            this.ui.get("BalanceSign").setEnabled(false);
        }
    }
}

//On change of account class - reset data before choosing another account
this.resetAccountInfo = function (value){
    this.ui.get("glAccountNo").setData("");
    this.ui.get("customerAccountNo").setData("");
    this.ui.get("AccountBalance").setData("");
    this.ui.get("AccountBranchCode").setData("");
    this.ui.get("BalanceSign").setData("");
    this.ui.get("accountCurrency").setData("");
    
    this.ui.get("standardExRate").setData("");
    this.ui.get("creditedAmountinAccCurrency").setData("");
    this.ui.get("negotiatedExRate").setData("");
    this.ui.get("verifiedText").setData("");
    
    this.accountNumVis(value);
}
this.setAmountInCurrencyForNostro = function(){
	var liqAmount  =  this.ui.get("LiquidationAmount").getData()? this.ui.get("LiquidationAmount").getData():0;
	var negoExRate =  this.ui.get("negotiatedExRate1").getData()? this.ui.get("negotiatedExRate1").getData():0;
	
	if( liqAmount > 0   &&   negoExRate > 0 )
		this.ui.get("debitedAmountinAccCurrency").setData(liqAmount * negoExRate);
}
 this.SetDebitAmountDetails = function(value){
	var exRate = this.context.options.debitexchangeRate.get("value");
	this.ui.get("standardExRate1").setData( Number(exRate.toFixed(6)));
	this.ui.get("negotiatedExRate1").setData( Number(exRate.toFixed(6)));

 }
  this.setNegoRateForNostro = function(value)
 {	

//	console.log("----------------------INSIDE setNegoRate");
  	var liqCurr   =  this.ui.get("LiquidateionCurrency").getData()? this.ui.get("LiquidateionCurrency").getData():"";  		 	
  	var accCurr   =  value.getData()? value.getData():""; 	 	

 	if ( liqCurr != "" && accCurr != "" && ( liqCurr == accCurr ) ) { 
		this.ui.get("standardExRate1").setData(1);
		this.ui.get("negotiatedExRate1").setData(1);
  		this.ui.get("negotiatedExRate1").setEnabled(false); 	
 	} 		

 	if ( liqCurr != "" && accCurr != "" && ( liqCurr != accCurr ) ){
		this.ui.get("negotiatedExRate1").setEnabled(true);
		concatedCurrency = {ccFrom : liqCurr , ccTo : accCurr , type:"TRANSFER" , sType:"S"};
		inputCurr = JSON.stringify(concatedCurrency);
		this.ui.get("GetExchangeRate1").execute(inputCurr);
 	}			
}
//++++++++++++++++++++++++++++++++++++++++++++++Error Handling+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
this.AjaxErrorHandling = function(errorMSG)
{
	this.context.options.alertMessage.set("value", errorMSG);
	this.context.options.errorVis.set("value", "EDITABLE")
}
this.showCADCheckBox = function()
{
	var choice = this.context.options.InformCADCheckBox.get("value");
	if(choice == true)
	{
		 this.ui.get("Horizontal_Layout3").setVisible(false, true);
	}
	else{
		this.ui.get("Horizontal_Layout3").setVisible(true, true);
	}
}
